ST.xhtml:
(* --- Herzschlag: +1 je Sekunde, beim Programmstart 0, 65535 -> 0 ---------------------------- *)
tJetzt := TIME();
IF NOT xGestartet THEN
    tLetzte := tJetzt;
    xGestartet := TRUE;
END_IF
udiSekunden := TIME_TO_UDINT(tJetzt - tLetzte) / 1000;
IF udiSekunden > 0 THEN
    uiHerzschlag := uiHerzschlag + UDINT_TO_UINT(udiSekunden AND 16#FFFF);
    tLetzte := tLetzte + UDINT_TO_TIME(udiSekunden * 1000);
END_IF

(* --- Kopf (0..11) ------------------------------------------------------------------------- *)
aBild[0] := 16#5650;   (* "VP" *)
aBild[1] := 16#455A;   (* "EZ" *)
VP_SetzeU32(aBild := aBild, uiAdresse := 2, udiWert := 16#01020304, xBekannt := TRUE);
aBild[4] := 16#0100;   (* Fassung 1.0 *)
aBild[5] := UINT_TO_WORD(uiTeAnzahl);
aBild[6] := UINT_TO_WORD(uiHerzschlag);
aBild[7] := UINT_TO_WORD(uiProgrammstand);
VP_SetzeU32(aBild := aBild, uiAdresse := 8, udiWert := udiSteuerungId, xBekannt := TRUE);
aBild[10] := UINT_TO_WORD(uiAnlagenart);
IF xMitNamen THEN
    aBild[11] := 140;
ELSE
    aBild[11] := 0;
END_IF

(* --- A: Anlage und Netzpunkt (12..21) ------------------------------------------------------ *)
wBits := VP_Bit(stAnlage.xNetzpunktGueltig, 0) OR VP_Bit(stAnlage.xNetzpunktBerechnet, 1)
    OR VP_Bit(stAnlage.xNetzpunktTot, 2) OR VP_Bit(stAnlage.xErzeugungGueltig, 3)
    OR VP_Bit(stAnlage.xGasspeicherGueltig, 4);
VP_SetzeU16(aBild := aBild, uiAdresse := 12, uiWert := WORD_TO_UINT(wBits), xBekannt := stAnlage.xGueltigBekannt);
VP_SetzeU16(aBild := aBild, uiAdresse := 13, uiWert := stAnlage.uiAlterS, xBekannt := stAnlage.xAlterBekannt);
VP_SetzeS32(aBild := aBild, uiAdresse := 14, diWert := stAnlage.diPNetzpunktW,
    xBekannt := stAnlage.xGueltigBekannt AND stAnlage.xNetzpunktGueltig);
VP_SetzeS32(aBild := aBild, uiAdresse := 16, diWert := stAnlage.diPErzeugungW,
    xBekannt := stAnlage.xGueltigBekannt AND stAnlage.xErzeugungGueltig);
VP_SetzeU16(aBild := aBild, uiAdresse := 18, uiWert := stAnlage.uiZustand, xBekannt := stAnlage.xZustandBekannt);
wBits := VP_Bit(stAnlage.xNotAus, 0) OR VP_Bit(stAnlage.xNaSchutz, 1) OR VP_Bit(stAnlage.xSammelstoerung, 2)
    OR VP_Bit(stAnlage.xHandOrt, 3) OR VP_Bit(stAnlage.xWartung, 4);
VP_SetzeU16(aBild := aBild, uiAdresse := 19, uiWert := WORD_TO_UINT(wBits), xBekannt := stAnlage.xBitsBekannt);
VP_SetzeU16(aBild := aBild, uiAdresse := 20, uiWert := stAnlage.uiSpeicherZehntelProzent,
    xBekannt := stAnlage.xGueltigBekannt AND stAnlage.xGasspeicherGueltig);
VP_SetzeU16(aBild := aBild, uiAdresse := 21, uiWert := stAnlage.uiInstalliertKw, xBekannt := stAnlage.xInstalliertBekannt);

(* --- N: Netzbetreiber (22..27) ------------------------------------------------------------- *)
VP_SetzeU16(aBild := aBild, uiAdresse := 22, uiWert := stNetzbetreiber.uiKanal, xBekannt := stNetzbetreiber.xKanalBekannt);
wBits := VP_Bit(stNetzbetreiber.xVorgabeGueltig, 0) OR VP_Bit(stNetzbetreiber.xVerbindungSteht, 1)
    OR VP_Bit(stNetzbetreiber.xWirkleistungBegrenzt, 2) OR VP_Bit(stNetzbetreiber.xNotAus, 3)
    OR VP_Bit(stNetzbetreiber.xCosPhiVorgabe, 4) OR VP_Bit(stNetzbetreiber.xKennlinie, 5);
VP_SetzeU16(aBild := aBild, uiAdresse := 23, uiWert := WORD_TO_UINT(wBits), xBekannt := stNetzbetreiber.xBitsBekannt);
(* Wort 24 ohne gültige Vorgabe: der wirksame Ersatzwert, nicht das Typ-Maximum (Vertrag §3) *)
VP_SetzeU16(aBild := aBild, uiAdresse := 24, uiWert := stNetzbetreiber.uiPZehntelProzent, xBekannt := stNetzbetreiber.xPBekannt);
VP_SetzeS16(aBild := aBild, uiAdresse := 25, iWert := stNetzbetreiber.iCosPhiTausendstel,
    xBekannt := stNetzbetreiber.xBitsBekannt AND stNetzbetreiber.xVorgabeGueltig);
VP_SetzeU16(aBild := aBild, uiAdresse := 26, uiWert := stNetzbetreiber.uiSeitS, xBekannt := stNetzbetreiber.xSeitBekannt);
aBild[27] := UINT_TO_WORD(stNetzbetreiber.uiZaehler);

(* --- D: Direktvermarkter (28..33) ---------------------------------------------------------- *)
VP_SetzeU16(aBild := aBild, uiAdresse := 28, uiWert := stDirektvermarkter.uiKanal, xBekannt := stDirektvermarkter.xKanalBekannt);
wBits := VP_Bit(stDirektvermarkter.xAbschnittGueltig, 0) OR VP_Bit(stDirektvermarkter.xAktivierung, 1)
    OR VP_Bit(stDirektvermarkter.xStopp, 2) OR VP_Bit(stDirektvermarkter.xBereitGemeldet, 3)
    OR VP_Bit(stDirektvermarkter.xAktivGemeldet, 4);
VP_SetzeU16(aBild := aBild, uiAdresse := 29, uiWert := WORD_TO_UINT(wBits), xBekannt := stDirektvermarkter.xBitsBekannt);
VP_SetzeU32(aBild := aBild, uiAdresse := 30, udiWert := stDirektvermarkter.udiSollW,
    xBekannt := stDirektvermarkter.xBitsBekannt AND stDirektvermarkter.xAbschnittGueltig);
VP_SetzeU16(aBild := aBild, uiAdresse := 32, uiWert := stDirektvermarkter.uiSeitS,
    xBekannt := stDirektvermarkter.xBitsBekannt AND stDirektvermarkter.xAbschnittGueltig);
(* d_zaehler hat keinen Ungültig-Wert; ohne gültigen Abschnitt liest ihn die Box nicht *)
aBild[33] := UINT_TO_WORD(stDirektvermarkter.uiZaehler);

(* --- S: Wirkung (34..37) ------------------------------------------------------------------- *)
VP_SetzeU16(aBild := aBild, uiAdresse := 34, uiWert := stWirkung.uiQuelle,
    xBekannt := stWirkung.xBitsBekannt AND stWirkung.xGueltig);
wBits := VP_Bit(stWirkung.xGueltig, 0) OR VP_Bit(stWirkung.xAnlageFolgt, 1);
VP_SetzeU16(aBild := aBild, uiAdresse := 35, uiWert := WORD_TO_UINT(wBits), xBekannt := stWirkung.xBitsBekannt);
VP_SetzeU32(aBild := aBild, uiAdresse := 36, udiWert := stWirkung.udiGrenzeW,
    xBekannt := stWirkung.xBitsBekannt AND stWirkung.xGueltig);

(* --- T: je Einheit 10 Wörter ab 38 + (n - 1) * 10 ------------------------------------------ *)
FOR n := 1 TO 10 DO
    uiBasis := 38 + (n - 1) * 10;
    IF n <= uiTeAnzahl THEN
        VP_SetzeU16(aBild := aBild, uiAdresse := uiBasis, uiWert := astEinheit[n].uiZustand,
            xBekannt := astEinheit[n].xBitsBekannt AND astEinheit[n].xWerteGueltig);
        wBits := VP_Bit(astEinheit[n].xWerteGueltig, 0) OR VP_Bit(astEinheit[n].xSollwertGueltig, 1)
            OR VP_Bit(astEinheit[n].xDvBereit, 2) OR VP_Bit(astEinheit[n].xDvAktiv, 3)
            OR VP_Bit(astEinheit[n].xGrundStoerung, 4) OR VP_Bit(astEinheit[n].xGrundNetzbetreiber, 5)
            OR VP_Bit(astEinheit[n].xGrundHandOrt, 6) OR VP_Bit(astEinheit[n].xGrundWartung, 7)
            OR VP_Bit(astEinheit[n].xGrundGasspeicherLeer, 8) OR VP_Bit(astEinheit[n].xGrundSonstiger, 9);
        VP_SetzeU16(aBild := aBild, uiAdresse := uiBasis + 1, uiWert := WORD_TO_UINT(wBits),
            xBekannt := astEinheit[n].xBitsBekannt);
        VP_SetzeU16(aBild := aBild, uiAdresse := uiBasis + 2, uiWert := astEinheit[n].uiArt,
            xBekannt := astEinheit[n].xArtBekannt);
        VP_SetzeU16(aBild := aBild, uiAdresse := uiBasis + 3, uiWert := astEinheit[n].uiNennKw,
            xBekannt := astEinheit[n].xNennBekannt);
        VP_SetzeS32(aBild := aBild, uiAdresse := uiBasis + 4, diWert := astEinheit[n].diPIstW,
            xBekannt := astEinheit[n].xBitsBekannt AND astEinheit[n].xWerteGueltig);
        VP_SetzeU32(aBild := aBild, uiAdresse := uiBasis + 6, udiWert := astEinheit[n].udiPSollW,
            xBekannt := astEinheit[n].xBitsBekannt AND astEinheit[n].xSollwertGueltig);
        VP_SetzeU32(aBild := aBild, uiAdresse := uiBasis + 8, udiWert := astEinheit[n].udiEZehntelKwh,
            xBekannt := astEinheit[n].xBitsBekannt AND astEinheit[n].xWerteGueltig);
    ELSE
        (* frei: nichts Altes aus einer früheren Zahl der Einheiten bleibt stehen *)
        FOR i := uiBasis TO uiBasis + 9 DO
            aBild[i] := 0;
        END_FOR
    END_IF
END_FOR
FOR i := 138 TO 139 DO
    aBild[i] := 0;
END_FOR

(* --- Namen ab 140: Netzbetreiber +0, Direktvermarkter +16, Typ der Einheit n +32 + (n - 1) * 16 *)
IF xMitNamen THEN
    VP_SetzeText(aBild := aBild, uiAdresse := 140, sText := sNetzbetreiber);
    VP_SetzeText(aBild := aBild, uiAdresse := 156, sText := sDirektvermarkter);
    FOR n := 1 TO 10 DO
        IF n <= uiTeAnzahl THEN
            VP_SetzeText(aBild := aBild, uiAdresse := 172 + (n - 1) * 16, sText := astEinheit[n].sTyp);
        ELSE
            VP_SetzeText(aBild := aBild, uiAdresse := 172 + (n - 1) * 16, sText := '');
        END_IF
    END_FOR
ELSE
    FOR i := 140 TO 331 DO
        aBild[i] := 0;
    END_FOR
END_IF

(* --- Herzschlag: +1 je Sekunde seit Programmstart, 65535 -> 0 ------------------------------ *)
tJetzt := TIME();
IF NOT xGestartet THEN
    tLetzte := tJetzt;
    xGestartet := TRUE;
END_IF
udiSekunden := TIME_TO_UDINT(tJetzt - tLetzte) / 1000;
IF udiSekunden > 0 THEN
    uiHerzschlag := uiHerzschlag + UDINT_TO_UINT(udiSekunden AND 16#FFFF);
    tLetzte := tLetzte + UDINT_TO_TIME(udiSekunden * 1000);
END_IF

(* --- Telegramm prüfen, wenn sich ein Wort geändert hat (Vertrag §5) ------------------------- *)
IF xErster THEN
    aLetzte := aWunschRegister;
    xErster := FALSE;
ELSE
    xGeaendert := FALSE;
    FOR i := 0 TO 63 DO
        IF aWunschRegister[i] <> aLetzte[i] THEN
            xGeaendert := TRUE;
        END_IF
    END_FOR
    IF xGeaendert THEN
        aLetzte := aWunschRegister;
        udiFrist := WORD_TO_UDINT(aWunschRegister[10]);
        uiGrund := 0;
        IF aWunschRegister[0] <> 16#5650 OR aWunschRegister[1] <> 16#4B57 THEN
            uiGrund := 2;
        ELSIF SHR(aWunschRegister[4], 8) <> 1 THEN
            uiGrund := 3;
        ELSIF aWunschRegister[2] <> 16#0102 OR aWunschRegister[3] <> 16#0304 THEN
            uiGrund := 4;
        ELSIF VP_KoppelSiegelW(aW := aWunschRegister) <> aWunschRegister[15] THEN
            uiGrund := 5;
        ELSIF VP_KoppelLiesU32(aW := aWunschRegister, uiAdresse := 8) <> udiSteuerungId THEN
            uiGrund := 6;
        ELSIF udiFrist < 5 OR udiFrist > 600 OR aWunschRegister[6] = 0 OR aWunschRegister[6] = 16#FFFF
                OR aWunschRegister[5] <> 8 THEN
            uiGrund := 7;
        END_IF
        IF uiGrund <> 0 THEN
            (* dieses Telegramm bewirkt nichts; das vorige gilt bis zu seiner Frist *)
            uiAbgelehnt := uiAbgelehnt + 1;
            uiKopfUrteil := uiGrund;
        ELSE
            aGilt := aWunschRegister;
            xHatTelegramm := TRUE;
            uiQSitzung := WORD_TO_UINT(aWunschRegister[6]);
            uiQHerzschlag := WORD_TO_UINT(aWunschRegister[7]);
            uiAngenommen := uiAngenommen + 1;
            tAnnahme := tJetzt;
            xLebt := TRUE;
            IF xFernsteuerungFrei THEN
                udiFristMs := MIN(udiFrist * 1000, TIME_TO_UDINT(tHoechsteFrist));
                xFristLaeuft := TRUE;
                uiKopfUrteil := 1;
            ELSE
                xFristLaeuft := FALSE;
                uiOhneFrist := 2;
                uiKopfUrteil := 9;
            END_IF
        END_IF
    END_IF
END_IF

(* --- Fernsteuerung entzogen: alle Wünsche fallen sofort ------------------------------------ *)
IF NOT xFernsteuerungFrei AND xFristLaeuft THEN
    xFristLaeuft := FALSE;
    uiOhneFrist := 2;
    uiKopfUrteil := 9;
END_IF

(* --- Frist: läuft von selbst ab ------------------------------------------------------------ *)
udiSeitMs := TIME_TO_UDINT(tJetzt - tAnnahme);
IF xFristLaeuft AND udiSeitMs >= udiFristMs THEN
    xFristLaeuft := FALSE;
    uiOhneFrist := 1;
    uiKopfUrteil := 8;
END_IF
IF xFristLaeuft THEN
    uiRestS := UDINT_TO_UINT((udiFristMs - udiSeitMs + 999) / 1000);
ELSE
    uiRestS := 0;
END_IF
(* einmal still, bleibt still: auch wenn TIME() nach 49 Tagen überläuft *)
IF xLebt AND udiSeitMs >= 15000 THEN
    xLebt := FALSE;
END_IF
xEdgeLebt := xLebt;

(* --- Kopf der Quittung (1000..1019, hier 0..19) -------------------------------------------- *)
aQuittungRegister[0] := 16#5650;   (* "VP" *)
aQuittungRegister[1] := 16#4B51;   (* "KQ" *)
VP_KoppelSetzeU32(aQ := aQuittungRegister, uiAdresse := 2, udiWert := 16#01020304);
aQuittungRegister[4] := 16#0100;   (* Fassung 1.0 *)
aQuittungRegister[6] := UINT_TO_WORD(uiHerzschlag);
aQuittungRegister[7] := UINT_TO_WORD(uiBibliothek);
VP_KoppelSetzeU32(aQ := aQuittungRegister, uiAdresse := 8, udiWert := udiSteuerungId);
aQuittungRegister[10] := UINT_TO_WORD(uiKopfUrteil);
aQuittungRegister[11] := UINT_TO_WORD(uiQSitzung);
aQuittungRegister[12] := UINT_TO_WORD(uiQHerzschlag);
aQuittungRegister[13] := UINT_TO_WORD(uiRestS);
aQuittungRegister[14] := VP_Bit(xGesetzt := xFernsteuerungFrei, uiBit := 0)
    OR VP_Bit(xGesetzt := xLebt, uiBit := 1) OR VP_Bit(xGesetzt := xHandOrt, uiBit := 2);
aQuittungRegister[15] := UINT_TO_WORD(uiAngenommen);
aQuittungRegister[16] := UINT_TO_WORD(uiAbgelehnt);
aQuittungRegister[17] := 0;
aQuittungRegister[18] := 0;

(* --- je Stellplatz: Angebot, Urteil, zugelassener Wert, wirksam (Vertrag §5) ---------------- *)
uiAnzahl := 0;
FOR n := 1 TO 8 DO
    uiW := 16 + (n - 1) * 6;
    uiQ := 20 + (n - 1) * 12;
    xLeer := aAngebot[n].uiArt = 0;
    xBereit := NOT xLeer AND aAngebot[n].xBereit AND NOT xHandOrt;
    uiUrteil := 0;
    diWert := 0;
    aWunsch[n].xGilt := FALSE;
    aWunsch[n].uiGrund := 0;
    IF NOT xLeer THEN
        uiAnzahl := uiAnzahl + 1;
    END_IF
    IF xHatTelegramm THEN
        uiArtW := WORD_TO_UINT(aGilt[uiW]);
        diW := UDINT_TO_DINT(SHL(WORD_TO_UDINT(aGilt[uiW + 2]), 16) OR WORD_TO_UDINT(aGilt[uiW + 3]));
        IF NOT xFristLaeuft THEN
            IF uiArtW <> 0 AND uiOhneFrist = 1 THEN
                uiUrteil := 7;
            ELSIF uiArtW <> 0 AND uiOhneFrist = 2 THEN
                uiUrteil := 5;
            END_IF
        ELSIF uiArtW = 0 THEN
            uiUrteil := 0;
        ELSIF xLeer OR uiArtW <> aAngebot[n].uiArt THEN
            uiUrteil := 3;
        ELSIF diW = 16#7FFFFFFF THEN
            uiUrteil := 4;
        ELSIF NOT xBereit THEN
            uiUrteil := 5;
        ELSE
            diWert := LIMIT(aAngebot[n].diMin, diW, aAngebot[n].diMax);
            IF aRueckmeldung[n].xUeberstimmt THEN
                uiUrteil := 6;
            ELSIF diWert <> diW THEN
                uiUrteil := 2;
            ELSE
                uiUrteil := 1;
            END_IF
            aWunsch[n].xGilt := TRUE;
            aWunsch[n].uiGrund := WORD_TO_UINT(aGilt[uiW + 1]);
        END_IF
        aQuittungRegister[uiQ + 9] := aGilt[uiW + 4];
    ELSE
        aQuittungRegister[uiQ + 9] := 0;
    END_IF
    aWunsch[n].diWert := diWert;
    aWunsch[n].uiUrteil := uiUrteil;
    aQuittungRegister[uiQ] := UINT_TO_WORD(aAngebot[n].uiArt);
    IF xLeer THEN
        aQuittungRegister[uiQ + 1] := 0;
        aQuittungRegister[uiQ + 2] := 0;
        aQuittungRegister[uiQ + 3] := 0;
    ELSE
        aQuittungRegister[uiQ + 1] := UINT_TO_WORD(aAngebot[n].uiZiel);
        aQuittungRegister[uiQ + 2] := UINT_TO_WORD(aAngebot[n].uiNr);
        aQuittungRegister[uiQ + 3] := VP_Bit(xGesetzt := xBereit, uiBit := 0)
            OR VP_Bit(xGesetzt := aAngebot[n].xGrundStoerung, uiBit := 1)
            OR VP_Bit(xGesetzt := aAngebot[n].xGrundHandOrt OR xHandOrt, uiBit := 2)
            OR VP_Bit(xGesetzt := aAngebot[n].xGrundWartung, uiBit := 3)
            OR VP_Bit(xGesetzt := aAngebot[n].xGrundVorrang, uiBit := 4)
            OR VP_Bit(xGesetzt := aAngebot[n].xGrundSonstiger, uiBit := 5);
    END_IF
    VP_KoppelSetzeS32(aQ := aQuittungRegister, uiAdresse := uiQ + 4, diWert := aAngebot[n].diMin, xBekannt := NOT xLeer);
    VP_KoppelSetzeS32(aQ := aQuittungRegister, uiAdresse := uiQ + 6, diWert := aAngebot[n].diMax, xBekannt := NOT xLeer);
    aQuittungRegister[uiQ + 8] := UINT_TO_WORD(uiUrteil);
    VP_KoppelSetzeS32(aQ := aQuittungRegister, uiAdresse := uiQ + 10, diWert := aRueckmeldung[n].diWirksam,
        xBekannt := aRueckmeldung[n].xWirksamBekannt);
END_FOR
aQuittungRegister[5] := UINT_TO_WORD(uiAnzahl);
aQuittungRegister[19] := VP_KoppelSiegelQ(aQ := aQuittungRegister);

IF xBekannt THEN
    aBild[uiAdresse] := UINT_TO_WORD(uiWert);
ELSE
    aBild[uiAdresse] := 16#FFFF;
END_IF
VP_SetzeU16 := xBekannt;

IF xBekannt THEN
    (* Zweierkomplement: INT_TO_WORD behält das Bitmuster *)
    aBild[uiAdresse] := INT_TO_WORD(iWert);
ELSE
    aBild[uiAdresse] := 16#7FFF;
END_IF
VP_SetzeS16 := xBekannt;

IF xBekannt THEN
    aBild[uiAdresse] := UDINT_TO_WORD(SHR(udiWert, 16));
    aBild[uiAdresse + 1] := UDINT_TO_WORD(udiWert AND 16#FFFF);
ELSE
    aBild[uiAdresse] := 16#FFFF;
    aBild[uiAdresse + 1] := 16#FFFF;
END_IF
VP_SetzeU32 := xBekannt;

IF xBekannt THEN
    (* Zweierkomplement über dieselbe Routine wie jeder 32-bit-Wert: DINT_TO_UDINT behält das Bitmuster *)
    VP_SetzeU32(aBild := aBild, uiAdresse := uiAdresse, udiWert := DINT_TO_UDINT(diWert), xBekannt := TRUE);
ELSE
    aBild[uiAdresse] := 16#7FFF;
    aBild[uiAdresse + 1] := 16#FFFF;
END_IF
VP_SetzeS32 := xBekannt;

iLaenge := LEN(sText);
FOR i := 0 TO 15 DO
    bHoch := 0;
    bNieder := 0;
    (* Hinter dem Ende des Texts steht 0, nie ein Rest aus dem Speicher der Zeichenkette *)
    IF 2 * i < iLaenge THEN
        bHoch := sText[2 * i];
    END_IF
    IF 2 * i + 1 < iLaenge THEN
        bNieder := sText[2 * i + 1];
    END_IF
    aBild[uiAdresse + INT_TO_UINT(i)] := SHL(BYTE_TO_WORD(bHoch), 8) OR BYTE_TO_WORD(bNieder);
END_FOR
VP_SetzeText := iLaenge > 0;

IF xGesetzt THEN
    VP_Bit := SHL(WORD#1, uiBit);
ELSE
    VP_Bit := 0;
END_IF

aQ[uiAdresse] := UDINT_TO_WORD(SHR(udiWert, 16));
aQ[uiAdresse + 1] := UDINT_TO_WORD(udiWert AND 16#FFFF);
VP_KoppelSetzeU32 := TRUE;

IF xBekannt THEN
    (* Zweierkomplement: DINT_TO_UDINT behält das Bitmuster *)
    VP_KoppelSetzeU32(aQ := aQ, uiAdresse := uiAdresse, udiWert := DINT_TO_UDINT(diWert));
ELSE
    aQ[uiAdresse] := 16#7FFF;
    aQ[uiAdresse + 1] := 16#FFFF;
END_IF
VP_KoppelSetzeS32 := xBekannt;

wC := wCrc;
FOR k := 0 TO 1 DO
    IF k = 0 THEN
        wByte := SHR(wWort, 8);
    ELSE
        wByte := wWort AND 16#00FF;
    END_IF
    wC := wC XOR wByte;
    FOR i := 1 TO 8 DO
        IF (wC AND 16#0001) <> 0 THEN
            wC := SHR(wC, 1) XOR 16#A001;
        ELSE
            wC := SHR(wC, 1);
        END_IF
    END_FOR
END_FOR
VP_KoppelCrcWort := wC;

wC := 16#FFFF;
FOR i := 0 TO 63 DO
    IF i <> 15 THEN
        wC := VP_KoppelCrcWort(wCrc := wC, wWort := aW[i]);
    END_IF
END_FOR
VP_KoppelSiegelW := wC;

wC := 16#FFFF;
FOR i := 0 TO 115 DO
    IF i <> 19 THEN
        wC := VP_KoppelCrcWort(wCrc := wC, wWort := aQ[i]);
    END_IF
END_FOR
VP_KoppelSiegelQ := wC;

IF NOT xEinmal THEN
    xEinmal := TRUE;
    stAnlage.xNetzpunktGueltig := TRUE;
    stAnlage.xErzeugungGueltig := TRUE;
    stAnlage.uiAlterS := 1;
    (* Einspeisung am Netzpunkt ist negativ: prüft das Zweierkomplement auf dem Gerät *)
    stAnlage.diPNetzpunktW := -1200;
    stAnlage.diPErzeugungW := 182700;
    stAnlage.uiZustand := 2;
    stAnlage.uiInstalliertKw := 265;
    stNb.uiKanal := 3;
    stNb.xVorgabeGueltig := TRUE;
    stNb.xVerbindungSteht := TRUE;
    stNb.xCosPhiVorgabe := TRUE;
    stNb.uiPZehntelProzent := 1000;
    stNb.iCosPhiTausendstel := -950;
    stNb.uiSeitS := 60;
    stNb.uiZaehler := 1;
    stDv.uiKanal := 0;
    stWirkung.xGueltig := TRUE;
    stWirkung.xAnlageFolgt := TRUE;
    stWirkung.uiQuelle := 0;
    stWirkung.udiGrenzeW := 265000;
    FOR n := 1 TO 3 DO
        astEinheit[n].xWerteGueltig := TRUE;
        astEinheit[n].xSollwertGueltig := TRUE;
        astEinheit[n].uiZustand := 2;
        astEinheit[n].uiArt := 1;
        astEinheit[n].uiNennKw := 125;
        astEinheit[n].diPIstW := 60800 + n * 100;
        astEinheit[n].udiPSollW := 125000;
        astEinheit[n].udiEZehntelKwh := 1000000 + INT_TO_UDINT(n);
    END_FOR
    astEinheit[1].sTyp := 'Probe-Wechselrichter 1';
    astEinheit[2].sTyp := 'Probe-Wechselrichter 2';
    astEinheit[3].sTyp := 'Probe-Wechselrichter 3 (Grün)';
    aAngebot[1].uiArt := 1;    (* limit_w *)
    aAngebot[1].uiZiel := 1;   (* erzeugung_gesamt *)
    aAngebot[1].diMin := 0;
    aAngebot[1].diMax := 375000;
    aAngebot[1].xBereit := TRUE;
    aAngebot[8].uiArt := 4;    (* on_off *)
    aAngebot[8].uiZiel := 7;   (* probe *)
    aAngebot[8].diMin := 0;
    aAngebot[8].diMax := 1;
    aAngebot[8].xBereit := TRUE;
END_IF
fbKoppel(udiSteuerungId := 1, xFernsteuerungFrei := TRUE, xHandOrt := FALSE, aAngebot := aAngebot,
    aRueckmeldung := aRueck, aWunschRegister := GVL_VoltPilot.aKoppelWunsch,
    aQuittungRegister := GVL_VoltPilot.aKoppelQuittung);
stWirkung.udiGrenzeW := 265000;
aRueck[1].xWirksamBekannt := FALSE;
IF fbKoppel.aWunsch[1].xGilt THEN
    stWirkung.udiGrenzeW := MIN(DINT_TO_UDINT(fbKoppel.aWunsch[1].diWert), 265000);
    aRueck[1].diWirksam := UDINT_TO_DINT(stWirkung.udiGrenzeW);
    aRueck[1].xWirksamBekannt := TRUE;
END_IF
GVL_VoltPilot.xProbeLampe := fbKoppel.aWunsch[8].xGilt AND fbKoppel.aWunsch[8].diWert = 1;
aRueck[8].diWirksam := BOOL_TO_DINT(GVL_VoltPilot.xProbeLampe);
aRueck[8].xWirksamBekannt := TRUE;
fbBild(udiSteuerungId := 1, uiProgrammstand := 2611, uiAnlagenart := 1, uiTeAnzahl := 3,
    stAnlage := stAnlage, stNetzbetreiber := stNb, stDirektvermarkter := stDv, stWirkung := stWirkung,
    astEinheit := astEinheit, xMitNamen := TRUE, sNetzbetreiber := 'Netzbetreiber Probe',
    sDirektvermarkter := '', aBild := GVL_VoltPilot.aErzeugerBild);
